"use client"

import {
  forwardRef,
  type ReactNode,
  type RefObject,
  useEffect,
  useId,
  useMemo,
  useRef,
} from "react"
import { useControllableState } from "../lib/hooks/use-controllable-state"
import { useDismiss } from "../lib/hooks/use-dismiss"
import { type Align, type Side, useFloating } from "../lib/hooks/use-floating"
import { usePresence } from "../lib/hooks/use-presence"
import { useReducedMotion } from "../lib/hooks/use-reduced-motion"
import { Layer } from "../lib/primitives/layer"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"
import { Button } from "../button/button"
import { focusInto, shouldReclaimFocus } from "../dialog/focus"

export interface CoachmarkStep {
  /** What the tip points at: a ref, or a CSS selector looked up when the step shows. */
  target: RefObject<HTMLElement | null> | string
  title: ReactNode
  content?: ReactNode
  side?: Side
  align?: Align
}

export interface CoachmarkLabels {
  next?: string
  back?: string
  done?: string
  skip?: string
  /** Builds the step counter, e.g. "2 of 4". */
  progress?: (step: number, total: number) => string
}

export interface CoachmarkProps {
  steps: readonly CoachmarkStep[]
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Zero-based index of the step on show. */
  step?: number
  defaultStep?: number
  onStepChange?: (step: number) => void
  /** Called when the last step's Done is pressed, before it closes. */
  onFinish?: () => void
  labels?: CoachmarkLabels
  className?: string
}

const TARGET_ATTRIBUTE = "data-kg-coachmark-target"

const resolve = (target: CoachmarkStep["target"]): HTMLElement | null =>
  typeof target === "string"
    ? document.querySelector<HTMLElement>(target)
    : target.current

/**
 * A guided tour: one anchored tip at a time, each pointing at a real control. Non-modal,
 * so the page stays usable; Escape or Skip ends it.
 */
export const Coachmark = forwardRef<HTMLDivElement, CoachmarkProps>(
  (
    {
      steps,
      open: openProp,
      defaultOpen = false,
      onOpenChange,
      step: stepProp,
      defaultStep = 0,
      onStepChange,
      onFinish,
      labels,
      className,
    },
    forwardedRef,
  ) => {
    const [openState, setOpen] = useControllableState({
      value: openProp,
      defaultValue: defaultOpen,
      onChange: onOpenChange,
    })
    const [index, setIndex] = useControllableState({
      value: stepProp,
      defaultValue: defaultStep,
      onChange: onStepChange,
    })
    const total = steps.length
    const current = steps[Math.min(Math.max(index, 0), total - 1)]
    const open = openState && current !== undefined
    const { ref, present, state } = usePresence<HTMLDivElement>(open)
    const composed = useComposedRefs(ref, forwardedRef)
    const reduced = useReducedMotion()
    const titleId = useId()
    const bodyId = useId()
    const returnTo = useRef<HTMLElement | null>(null)

    const anchor = useMemo<RefObject<HTMLElement | null>>(
      () => ({
        get current() {
          return current && typeof document !== "undefined"
            ? resolve(current.target)
            : null
        },
      }),
      [current],
    )

    useFloating(anchor, ref, {
      open,
      side: current?.side ?? "bottom",
      align: current?.align ?? "center",
      offset: 14,
      padding: 12,
    })

    useEffect(() => {
      const node = open ? anchor.current : null
      if (!node) return
      node.setAttribute(TARGET_ATTRIBUTE, "")
      node.scrollIntoView?.({ block: "nearest", behavior: reduced ? "auto" : "smooth" })
      return () => node.removeAttribute(TARGET_ATTRIBUTE)
    }, [open, anchor, reduced])

    useEffect(() => {
      if (!open) return
      const active = document.activeElement
      returnTo.current = active instanceof HTMLElement ? active : null
      const node = ref.current
      if (node) focusInto(node, node.querySelector<HTMLElement>("[data-primary]"))
      return () => {
        const back = returnTo.current
        if (back?.isConnected && shouldReclaimFocus(ref.current)) back.focus()
      }
    }, [open])

    const close = () => setOpen(false)
    useDismiss({ enabled: open, outside: false, refs: [ref], onDismiss: close })

    if (!present || !current) return null

    const position = Math.min(Math.max(index, 0), total - 1)
    const last = position === total - 1
    const progress = labels?.progress ?? ((n: number, of: number) => `${n} of ${of}`)

    return (
      <Layer
        ref={composed}
        role="dialog"
        aria-labelledby={titleId}
        aria-describedby={current.content != null ? bodyId : undefined}
        className={cx(
          "kg-coachmark grid gap-3 w-[min(20rem,calc(100vw-1.5rem))] p-4 text-kg-fg z-kg-popover",
          "bg-kg-surface border-2 border-kg-ink rounded-kg-xl shadow-kg-lg origin-(--kg-origin,center)",
          "data-[side=top]:[--kg-enter-y:4px] data-[side=bottom]:[--kg-enter-y:-4px]",
          "data-[state=open]:animate-[kg-pop-in_var(--kg-duration-base)_var(--kg-ease-out)]",
          "data-[state=closed]:pointer-events-none data-[state=closed]:animate-[kg-fade-out_var(--kg-duration-fast)_var(--kg-ease-in)_forwards]",
          className,
        )}
        data-state={state}
      >
        <div className="kg-coachmark__meta flex items-center justify-between gap-3">
          <span className="kg-coachmark__progress text-kg-xs font-semibold tabular-nums text-kg-accent-strong">
            {progress(position + 1, total)}
          </span>
          <span className="kg-coachmark__dots inline-flex gap-[5px]" aria-hidden="true">
            {steps.map((_, dot) => (
              <span
                key={dot}
                className={cx(
                  "kg-coachmark__dot size-[6px] rounded-full",
                  "transition-[background-color,scale] duration-(--kg-duration-base) ease-kg-out",
                  dot === position
                    ? "bg-kg-accent scale-135"
                    : dot < position
                      ? "bg-kg-fg-muted"
                      : "bg-kg-border-strong",
                )}
                data-active={dot === position || undefined}
                data-done={dot < position || undefined}
              />
            ))}
          </span>
        </div>
        <div key={position} className="kg-coachmark__content grid gap-1.5 animate-[kg-fade-in_var(--kg-duration-base)_var(--kg-ease-out)]">
          <div id={titleId} className="kg-coachmark__title text-kg-md font-semibold leading-[1.3] tracking-[-0.01em]">
            {current.title}
          </div>
          {current.content != null && (
            <div id={bodyId} className="kg-coachmark__body text-kg-sm leading-[1.55] text-kg-fg-muted">
              {current.content}
            </div>
          )}
        </div>
        <div className="kg-coachmark__footer flex items-center justify-between gap-2 -mx-1">
          {last ? (
            <span />
          ) : (
            <Button size="sm" variant="ghost" onClick={close}>
              {labels?.skip ?? "Skip tour"}
            </Button>
          )}
          <span className="kg-coachmark__nav inline-flex gap-1.5">
            {position > 0 && (
              <Button
                size="sm"
                variant="outline"
                onClick={() => setIndex(position - 1)}
              >
                {labels?.back ?? "Back"}
              </Button>
            )}
            <Button
              size="sm"
              data-primary=""
              onClick={() => {
                if (!last) {
                  setIndex(position + 1)
                  return
                }
                onFinish?.()
                close()
              }}
            >
              {last ? (labels?.done ?? "Done") : (labels?.next ?? "Next")}
            </Button>
          </span>
        </div>
      </Layer>
    )
  },
)

Coachmark.displayName = "Coachmark"

@layer kg.components {
  /* The element the current step points at is any element on the page, so it can't take utilities. */
  [data-kg-coachmark-target] {
    outline: 2px solid var(--kg-ink);
    outline-offset: 4px;
    transition: outline-offset var(--kg-duration-slow) var(--kg-ease-out);
  }
}

"use client"

import { forwardRef, useEffect, useRef, useState } from "react"
import { Layer } from "../lib/primitives/layer"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"

export interface HintLayerProps {
  /** Elements carrying this attribute show its text as a hint. */
  attribute?: string
  /** Also take over native `title` tooltips, keeping their text as the accessible description. */
  replaceTitles?: boolean
  /** Gap between the pointer and the hint, in px. */
  offset?: number
  className?: string
}

/**
 * One hint surface for a whole app, ported from the dashboard: anything with `data-hint`
 * (or a `title`) shows a styled hint that follows the pointer, and a keyboard focus shows it
 * under the element. Lines split on newlines; the first is bold when there are several.
 */
export const HintLayer = forwardRef<HTMLDivElement, HintLayerProps>(
  (
    { attribute = "data-hint", replaceTitles = false, offset = 14, className },
    forwardedRef,
  ) => {
    const [lines, setLines] = useState<string[] | null>(null)
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const point = useRef({ x: 0, y: 0, below: false })

    const place = () => {
      const node = local.current
      if (!node) return
      const { x, y, below } = point.current
      const flipX = x + node.offsetWidth + offset > window.innerWidth
      const flipY = !below && y + node.offsetHeight + offset > window.innerHeight
      node.style.left = `${Math.round(flipX ? x - offset - node.offsetWidth : below ? x : x + offset)}px`
      node.style.top = `${Math.round(flipY ? y - offset - node.offsetHeight : below ? y : y + offset)}px`
    }

    useEffect(() => {
      const selector = replaceTitles ? `[${attribute}], [title]` : `[${attribute}]`
      let current: HTMLElement | null = null
      let frame = 0

      const textOf = (host: HTMLElement) => {
        const native = replaceTitles ? host.getAttribute("title") : null
        if (native) {
          host.setAttribute(attribute, native)
          host.removeAttribute("title")
        }
        const text = host.getAttribute(attribute)
        // The hint itself is hidden from assistive tech, so its text lives on as the
        // host's description, as a title's would have.
        if (
          text &&
          !["aria-label", "aria-describedby", "aria-description"].some((name) =>
            host.hasAttribute(name),
          )
        )
          host.setAttribute("aria-description", text)
        return text
      }

      const show = (host: HTMLElement, x: number, y: number, below: boolean) => {
        const text = textOf(host)
        if (!text) return
        current = host
        point.current = { x, y, below }
        setLines(text.split("\n").filter(Boolean))
      }

      const hide = () => {
        cancelAnimationFrame(frame)
        current = null
        setLines(null)
      }

      const over = (event: PointerEvent) => {
        if (event.pointerType === "touch") return
        const host = (event.target as Element | null)?.closest?.<HTMLElement>(selector)
        if (host && host !== current) show(host, event.clientX, event.clientY, false)
      }
      const move = (event: PointerEvent) => {
        if (!current) return
        point.current = { x: event.clientX, y: event.clientY, below: false }
        cancelAnimationFrame(frame)
        frame = requestAnimationFrame(place)
      }
      const out = (event: PointerEvent) => {
        const next = event.relatedTarget as Node | null
        if (current && !(next && current.contains(next))) hide()
      }
      const focusIn = (event: FocusEvent) => {
        const host = (event.target as Element | null)?.closest?.<HTMLElement>(selector)
        if (!host || !host.matches(":focus-visible")) return
        const rect = host.getBoundingClientRect()
        show(host, rect.left, rect.bottom + 6, true)
      }
      const key = (event: KeyboardEvent) => {
        if (event.key === "Escape" && current) hide()
      }

      document.addEventListener("pointerover", over)
      document.addEventListener("pointermove", move, { passive: true })
      document.addEventListener("pointerout", out)
      document.addEventListener("pointerdown", hide)
      document.addEventListener("focusin", focusIn)
      document.addEventListener("focusout", hide)
      document.addEventListener("keydown", key)
      window.addEventListener("scroll", hide, { capture: true, passive: true })
      return () => {
        cancelAnimationFrame(frame)
        document.removeEventListener("pointerover", over)
        document.removeEventListener("pointermove", move)
        document.removeEventListener("pointerout", out)
        document.removeEventListener("pointerdown", hide)
        document.removeEventListener("focusin", focusIn)
        document.removeEventListener("focusout", hide)
        document.removeEventListener("keydown", key)
        window.removeEventListener("scroll", hide, { capture: true })
      }
    }, [attribute, replaceTitles])

    useEffect(() => {
      if (lines) place()
    })

    if (!lines || lines.length === 0) return null
    const [head, ...rest] = lines

    return (
      <Layer
        ref={ref}
        role="tooltip"
        aria-hidden="true"
        className={cx(
          "kg-hint-layer grid gap-[2px] max-w-[min(18rem,calc(100vw-1rem))] px-3 py-2 text-kg-xs leading-[1.45] text-kg-fg",
          "bg-kg-surface border-2 border-kg-ink rounded-kg-md shadow-kg-sm pointer-events-none z-kg-tooltip",
          "animate-[kg-fade-in_var(--kg-duration-fast)_var(--kg-ease-out)]",
          className,
        )}
      >
        {rest.length > 0 ? (
          <strong className="kg-hint-layer__head font-semibold">{head}</strong>
        ) : (
          <span>{head}</span>
        )}
        {rest.map((line, index) => (
          <span key={`${index}-${line}`} className="kg-hint-layer__line text-kg-fg-muted">
            {line}
          </span>
        ))}
      </Layer>
    )
  },
)

HintLayer.displayName = "HintLayer"
